#include <stdio.h>
#include <string.h>

static int normalize(int cp) {
    switch (cp) {
        case 0x00C0: case 0x00C1: case 0x00C2: case 0x00C3: case 0x00C4:
        case 0x00E0: case 0x00E1: case 0x00E2: case 0x00E3: case 0x00E4:
            return 'a';
        case 0x00C8: case 0x00C9: case 0x00CA: case 0x00CB:
        case 0x00E8: case 0x00E9: case 0x00EA: case 0x00EB:
            return 'e';
        case 0x00CC: case 0x00CD: case 0x00CE: case 0x00CF:
        case 0x00EC: case 0x00ED: case 0x00EE: case 0x00EF:
            return 'i';
        case 0x00D2: case 0x00D3: case 0x00D4: case 0x00D5: case 0x00D6:
        case 0x00F2: case 0x00F3: case 0x00F4: case 0x00F5: case 0x00F6:
            return 'o';
        case 0x00D9: case 0x00DA: case 0x00DB: case 0x00DC:
        case 0x00F9: case 0x00FA: case 0x00FB: case 0x00FC:
            return 'u';
        case 0x00C7: case 0x00E7:
            return 'c';
        default:
            return cp;
    }
}

static int decode(const char *s, int out[]) {
    int n = 0;
    const unsigned char *p = (const unsigned char *)s;

    while (*p && *p != '\n' && *p != '\r' && *p != ' ' && *p != '\t') {
        int cp;
        if (*p < 0x80) {
            cp = *p++;
        } else if ((*p & 0xE0) == 0xC0) {
            cp = ((*p & 0x1F) << 6) | (p[1] & 0x3F);
            p += 2;
        } else if ((*p & 0xF0) == 0xE0) {
            cp = ((*p & 0x0F) << 12) | ((p[1] & 0x3F) << 6) | (p[2] & 0x3F);
            p += 3;
        } else {
            cp = ((*p & 0x07) << 18) | ((p[1] & 0x3F) << 12) |
                 ((p[2] & 0x3F) << 6) | (p[3] & 0x3F);
            p += 4;
        }
        out[n++] = normalize(cp);
    }

    return n;
}

int main(void) {
    char line[1024];
    int p[128], a[128], used[128] = {0};

    if (!fgets(line, sizeof(line), stdin)) return 0;
    int np = decode(line, p);

    if (!fgets(line, sizeof(line), stdin)) return 0;
    int na = decode(line, a);

    if (np != na) {
        puts("N");
        return 0;
    }

    int ok = 1;
    for (int i = 0; i < na && ok; i++) {
        if (a[i] == '*') continue;

        int found = 0;
        for (int j = 0; j < np; j++) {
            if (!used[j] && p[j] == a[i]) {
                used[j] = 1;
                found = 1;
                break;
            }
        }
        if (!found) ok = 0;
    }

    puts(ok ? "S" : "N");
    return 0;
}
